#!/bin/bash
# usage: secmap.sh a b  -> pages for exercise section keywords (Telugu)
for k in "అవగాహన" "అపరిచిత పద్య" "అపరిచిత గద్య" "అర్థసందర్భ" "ఏకవాక్య" "నాలుగైదు" "ఎనిమిది నుండి" "సృజనాత్మకంగా" "ఎరుపు" "పర్యాయ" "నానార్థ" "వ్యుత్పత్త్య" "వికృతి" "జాతీయ" "విడదీసి" "కలిపి" "విగ్రహ" "అలంకార" "గురు" "కర్మణి" "ప్రత్యక్ష" "ఆధునిక" "ప్రాజెక్టు"; do echo "$k: $(grep -l "$k" $(seq -f "ocr_tel/%g.txt" $1 $2) 2>/dev/null | sed 's|ocr_tel/||;s|.txt||' | tr '\n' ' ')"; done
